# region: gather
def gather(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.lstrip('-').isdigit():
            out.append(int(s))
            return out
    return out

# region: render
def render(xs, factor=3):
    return [v * factor for v in xs]

# region: emit
def emit(xs, floor_=6):
    return [v for v in xs if v >= floor_]

# region: sift
def sift(xs):
    return {'n': len(xs), 'total': sum(xs)}

# region: digest
def digest(summary):
    out = dict(summary)
    out['flags'] = sorted(k for k, v in summary.items() if isinstance(v, int) and v > 0)
    return out

# region: run
def run(raw):
    return digest(sift(emit(render(gather(raw)))))

